pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const users = pm.response.json();

pm.test("Response is a non-empty array", function () {
    pm.expect(users).to.be.an("array");
    pm.expect(users.length).to.be.greaterThan(0);
});

pm.test("Response contains user information", function () {
    pm.expect(users[0]).to.be.an("object");
});

pm.test("Every user has id, name and email", function () {
    users.forEach(user => {
        pm.expect(user).to.have.property("id");
        pm.expect(user).to.have.property("name");
        pm.expect(user).to.have.property("email");
    });
});

const userId = users[0].id;
pm.collectionVariables.set("userId", userId);

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const data = pm.response.json();
const userId = Number(pm.collectionVariables.get("userId"));

pm.test("Returned ID matches saved ID", function () {
    pm.expect(data.id).to.eql(userId);
});

pm.test("Phone is present and not empty", function () {
    pm.expect(data).to.have.property("phone");
    pm.expect(data.phone).to.not.be.empty;
});

